package com.lgremote.app;
import android.app.Activity; import android.os.Bundle; import android.webkit.*; import android.view.View; import org.json.*; import okhttp3.*; import java.net.*; import java.util.concurrent.*; import javax.net.ssl.*; import java.security.cert.X509Certificate;
public class MainActivity extends Activity {
 WebView view; OkHttpClient client; WebSocket tv,pointer; String host=""; boolean ready=false; int seq=0; final ExecutorService worker=Executors.newSingleThreadExecutor(); final ConcurrentHashMap<String,CompletableFuture<JSONObject>> pending=new ConcurrentHashMap<>();
 void ui(String id,String msg){runOnUiThread(()->view.evaluateJavascript("document.getElementById("+JSONObject.quote(id)+").textContent="+JSONObject.quote(msg),null));}
 JSONObject obj(Object... pairs) throws JSONException {JSONObject j=new JSONObject();for(int i=0;i<pairs.length;i+=2)j.put((String)pairs[i],pairs[i+1]);return j;}
 @Override public void onCreate(Bundle b){super.onCreate(b);view=new WebView(this);setContentView(view);view.setFitsSystemWindows(true);view.getSettings().setJavaScriptEnabled(true);view.getSettings().setDomStorageEnabled(true);view.getSettings().setAllowFileAccess(false);view.getSettings().setAllowContentAccess(false);view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});view.addJavascriptInterface(new Bridge(),"NativeRemote");view.loadUrl("file:///android_asset/index.html");}
 boolean privateIp(String s){String[] a=s.split("\\.",-1);if(a.length!=4)return false;int[] n=new int[4];try{for(int i=0;i<4;i++){if(!a[i].matches("[0-9]{1,3}"))return false;n[i]=Integer.parseInt(a[i]);if(n[i]>255)return false;}}catch(Exception e){return false;}return n[0]==10||n[0]==192&&n[1]==168||n[0]==172&&n[1]>=16&&n[1]<=31;}
 void connect(String ip)throws Exception{if(!privateIp(ip))throw new Exception("Enter a private IPv4 address");ready=false;if(tv!=null)tv.cancel();if(pointer!=null)pointer.cancel();pointer=null;host=ip;X509TrustManager trust=new X509TrustManager(){public void checkClientTrusted(X509Certificate[] c,String a){}public void checkServerTrusted(X509Certificate[] c,String a){}public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}};SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,new TrustManager[]{trust},null);client=new OkHttpClient.Builder().sslSocketFactory(ssl.getSocketFactory(),trust).hostnameVerifier((h,s)->h.equals(ip)).connectTimeout(6,TimeUnit.SECONDS).build();ui("status","Connecting…");open(ip,true);}
 void open(String ip,boolean secure){tv=client.newWebSocket(new Request.Builder().url((secure?"wss://":"ws://")+ip+(secure?":3001":":3000")).build(),new WebSocketListener(){boolean opened=false;public void onOpen(WebSocket s,Response r){if(s!=tv)return;opened=true;try{String[] p={"LAUNCH","LAUNCH_WEBAPP","APP_TO_APP","CONTROL_AUDIO","CONTROL_INPUT_MEDIA_PLAYBACK","CONTROL_INPUT_TV","CONTROL_POWER","READ_INSTALLED_APPS","READ_INPUT_DEVICE_LIST","READ_NETWORK_STATE","CONTROL_MOUSE_AND_KEYBOARD","CONTROL_INPUT_JOYSTICK"};JSONObject payload=obj("pairingType","PROMPT","manifest",obj("manifestVersion",1,"appVersion","1.0","permissions",new JSONArray(java.util.Arrays.asList(p))));String key=getPreferences(0).getString(ip,"");if(!key.isEmpty())payload.put("client-key",key);s.send(obj("id","register","type","register","payload",payload).toString());ui("status","Accept pairing on TV");}catch(Exception e){ui("status",e.toString());}}public void onMessage(WebSocket s,String raw){if(s!=tv)return;try{JSONObject j=new JSONObject(raw);String id=j.optString("id");if(j.optString("type").equals("registered")){ready=true;String key=j.optJSONObject("payload").optString("client-key");if(!key.isEmpty())getPreferences(0).edit().putString(ip,key).apply();ui("status","Connected");}else if(id.equals("register")&&j.optString("type").equals("error")){ui("status",j.optString("error","Pairing failed"));}else{CompletableFuture<JSONObject> f=pending.remove(id);if(f!=null)f.complete(j);}}catch(Exception e){ui("feedback",e.toString());}}public void onFailure(WebSocket s,Throwable t,Response r){if(s!=tv)return;ready=false;if(secure&&!opened){open(ip,false);}else ui("status","Connection failed: "+t.getMessage());}public void onClosed(WebSocket s,int c,String r){if(s==tv){ready=false;ui("status","Disconnected");}}});}
 JSONObject request(String uri,JSONObject payload)throws Exception{if(!ready)throw new Exception("Connect TV first");String id="r"+(++seq);CompletableFuture<JSONObject> f=new CompletableFuture<>();pending.put(id,f);try{if(!tv.send(obj("id",id,"type","request","uri","ssap://"+uri,"payload",payload).toString()))throw new Exception("Disconnected");JSONObject j=f.get(8,TimeUnit.SECONDS);JSONObject p=j.optJSONObject("payload");if(j.optString("type").equals("error")||p==null||!p.optBoolean("returnValue",true))throw new Exception(j.optString("error","TV rejected command"));return p;}finally{pending.remove(id);}}
 void button(String k)throws Exception{if(pointer==null){String path=request("com.webos.service.networkinput/getPointerInputSocket",obj()).getString("socketPath");URI u=URI.create(path);if(!host.equals(u.getHost())||!("ws".equals(u.getScheme())||"wss".equals(u.getScheme())))throw new Exception("Unexpected TV socket");CompletableFuture<Boolean> f=new CompletableFuture<>();pointer=client.newWebSocket(new Request.Builder().url(path).build(),new WebSocketListener(){public void onOpen(WebSocket s,Response r){f.complete(true);}public void onFailure(WebSocket s,Throwable t,Response r){f.completeExceptionally(t);if(pointer==s)pointer=null;}public void onClosed(WebSocket s,int c,String r){if(pointer==s)pointer=null;}});try{f.get(8,TimeUnit.SECONDS);}catch(Exception e){if(pointer!=null)pointer.cancel();pointer=null;throw e;}}if(pointer==null||!pointer.send("type:button\nname:"+k+"\n\n"))throw new Exception("Navigation socket disconnected");}
 void command(String k)throws Exception{if(!ready)throw new Exception("Connect TV first");switch(k){case "VOLUP":request("audio/volumeUp",obj());break;case "VOLDOWN":request("audio/volumeDown",obj());break;case "CHUP":request("tv/channelUp",obj());break;case "CHDOWN":request("tv/channelDown",obj());break;case "OFF":request("system/turnOff",obj());break;case "PLAY":request("media.controls/play",obj());break;case "PAUSE":request("media.controls/pause",obj());break;case "MUTE":request("audio/setMute",obj("mute",!request("audio/getMute",obj()).getBoolean("mute")));break;case "HOTSTAR":{JSONArray apps=request("com.webos.applicationManager/listApps",obj()).optJSONArray("apps");String appId="";if(apps!=null)for(int i=0;i<apps.length();i++){JSONObject app=apps.optJSONObject(i);if(app==null)continue;String id=app.optString("id");String title=app.optString("title");if((id+" "+title).toLowerCase(java.util.Locale.ROOT).contains("hotstar")&&!id.isEmpty()){appId=id;break;}}if(appId.isEmpty())throw new Exception("JioHotstar not found on TV");request("system.launcher/launch",obj("id",appId));break;}case "NETFLIX":case "YOUTUBE":request("system.launcher/launch",obj("id",k.equals("NETFLIX")?"netflix":"youtube.leanback.v4"));break;default:if(k.matches("UP|DOWN|LEFT|RIGHT|ENTER|HOME|BACK|MENU|INFO|[0-9]"))button(k);else throw new Exception("Unknown command");}}
 void wake(String mac)throws Exception{mac=mac.replace(":","").replace("-","");if(!mac.matches("(?i)[0-9a-f]{12}"))throw new Exception("Enter TV MAC address");byte[] b=new byte[102];java.util.Arrays.fill(b,0,6,(byte)255);for(int i=6;i<102;i++)b[i]=(byte)Integer.parseInt(mac.substring((i-6)%6*2,(i-6)%6*2+2),16);try(DatagramSocket s=new DatagramSocket()){s.setBroadcast(true);s.send(new DatagramPacket(b,b.length,InetAddress.getByName("255.255.255.255"),9));}}
 interface Job{void run()throws Exception;} void submit(Job j){worker.submit(()->{try{j.run();ui("feedback","Request sent");}catch(Exception e){ui("feedback",e.getMessage()==null?e.toString():e.getMessage());}});}
 class Bridge{@JavascriptInterface public void connect(String ip){submit(()->MainActivity.this.connect(ip));}@JavascriptInterface public void command(String k){submit(()->MainActivity.this.command(k));}@JavascriptInterface public void wake(String m){submit(()->MainActivity.this.wake(m));}}
 @Override protected void onDestroy(){if(tv!=null)tv.cancel();if(pointer!=null)pointer.cancel();worker.shutdownNow();view.destroy();super.onDestroy();}
}
